files.types/index.d.ts:
export type Ttl = '5m' | '1h'

export type Info = {
  model: string | null
  effort: string | null
  lastRequestAt: number | null
  ttl: Ttl | null
}

export type Entry = { kind: 'think' | 'say' | 'tool' | 'result' | 'error'; text: string }

export type Agent = {
  id: string | null
  toolUseId: string
  description: string
  type: string
  prompt: string
  model: string | null
  isBackground: boolean
  isTeammate: boolean
  startedAt: number
  endedAt: number | null
  history: Entry[]
}

export type FileChange = {
  path: string
  status: 'added' | 'modified' | 'deleted'
  added: number
  removed: number
}

export type Commit = { hash: string; subject: string; body: string; at: number; isPushed: boolean }

export type RepoChanges = { root: string; branch: string; files: FileChange[]; commits: Commit[] }

export type Picker = 'model' | 'effort' | null

export type Quota = {
  label: string
  used: number
  /** Share of the window elapsed, 0 to 1; null while the reset time is unknown. */
  elapsed: number | null
  /** Where the average burn lands at the reset, or when the limit runs out. */
  verdict: { text: string; tone: 'ok' | 'tight' | 'out' } | null
  /** Milliseconds until the window resets. */
  resetsIn: number | null
}

export type Step = {
  id: string
  /** What the step did, in the agent's own words (a Bash call's description). */
  label: string
  /** How: the command, path or pattern. */
  how?: string
  /** Why: the first sentence of the thinking before it. */
  why?: string
  toolIds?: string[]
  /** The calls of `toolIds` that have returned. */
  doneIds?: string[]
  /** The model's answer has streamed in full. */
  isDone: boolean
  /** Refused or failed calls, and the same action taken again. */
  flag?: 'refused' | 'failed' | 'repeat'
  note?: string
  repeats?: number
}

export type TrackedIssue = {
  platform: 'github' | 'linear'
  /** `owner/repo#N` or `KEY-N`. */
  key: string
  title: string | null
  url: string | null
  /** Linear's desktop link, opened instead of `url` where the app is installed. */
  appUrl: string | null
  rank: number
}

export type TrackedPr = {
  repo: string
  number: number
  title: string | null
  url: string
  state: 'draft' | 'open' | 'closed' | 'merged' | null
  rank: number
}

export type Tracker = {
  issue: TrackedIssue | null
  /** One pull request per repository, `owner/repo`. */
  prs: TrackedPr[]
  /** Bare `KEY-N` identifiers the prompts named, matched once a Linear tool shows one. */
  mentioned: string[]
}

/** A repository the session worked on: its git common dir, `owner/repo` from its origin, its name, and the linked worktree it last edited in. */
export type Repo = { common: string; slug: string | null; name: string; worktree: string | null }

/** A handover file, with its length and last change (epoch ms) as read, null when unread. */
export type HandoverFile = { path: string; title: string | null; lines: number | null; modifiedAt: number | null }

export type Handover = {
  /** The handover plugin runs in this session. */
  isOn: boolean
  /** The handover this session started from, and the one it wrote. */
  loaded: HandoverFile | null
  written: HandoverFile | null
  suggest: number
  trigger: number
  warn: number
  isWriting: boolean
  /** The wind-down has started (the trigger, a request or /handover:trigger): no new task, those in progress finish. */
  isWindingDown: boolean
  error: string | null
  /** The message the closing reply gives the next session to start on, once the handover is written. */
  resume: string | null
}

/** The pane's tabs: the session at a glance, the rest (steps, sub-agents, git), the values it reads from configuration, and what each item means. */
/** A typed prompt and when it was submitted (epoch ms); `at` null for one read back from the transcript. */
export type Prompt = { text: string; at: number | null }

export type Tab = 'main' | 'misc' | 'config' | 'help'

/** Something tangible the session wrote: an artifact it published, or a Markdown file outside the project. */
export type Doc = {
  /** Its real path, or the artifact's link: one entry each. */
  id: string
  /** The path as written, or the artifact's link. */
  path: string
  /** `Artifacts`, `Agent handovers`, `Plans`, else its folder's name. */
  kind: string
  /** Its file name without `.md`, or the artifact's title. */
  name: string
}

/** The values the pane reads from configuration, as set; null where unset and the default applies. */
export type Config = {
  cacheTtl: Ttl
  autoCompactWindow: number | null
  tokenLimit: number | null
  tokenReserve: number | null
  plansDirectory: string | null
  handoverDir: string | null
}

declare module 'claude-code' {
  interface PluginState {
    'session-panel': {
      info: Info
      agents: Agent[]
      steps: Step[]
      expanded: string | null
      stepsOpen: boolean
      picking: Picker
      prompts: (Prompt | string)[]
      view: 'overview' | 'prompts'
      roots: string[]
      changes: RepoChanges[]
      tracker: Tracker
      home: string | null
      handover: Handover | null
      repos: Repo[]
      documents: Doc[]
      config: Config
      tab: Tab
      quotasOpen: boolean
      topic: string | null
      /** The session whose title is set (by the agent or from its handover), and the one already reminded to set it. */
      titled: { set: string | null; reminded: string | null }
    }
  }
}
